import * as ts from 'typescript';
import * as util from '../util';
import { Mutator } from './Mutator';

type MethodLikeProperty = ts.ConstructorDeclaration | ts.MethodDeclaration |
  ts.SetAccessorDeclaration | ts.GetAccessorDeclaration;

type PropertySubstitution = ts.PropertyDeclaration | ts.GetAccessorDeclaration |
  ts.SetAccessorDeclaration;

export class ClassDeclarationMutator extends Mutator {

  protected kind = ts.SyntaxKind.ClassDeclaration;
  protected initializers: ts.Statement[] = [];

  protected mutate(node: ts.ClassDeclaration): ts.Node {
    const members: ts.ClassElement[] = [];

    const decorators = this.options.noAnnotate ?
      (ts.canHaveDecorators(node) ? ts.getDecorators(node) : undefined) : this.reflectClass(node);

    for (let member of node.members) {
      switch (member.kind) {
        case ts.SyntaxKind.Constructor:
        case ts.SyntaxKind.MethodDeclaration:
        case ts.SyntaxKind.GetAccessor:
        case ts.SyntaxKind.SetAccessor:
          members.push(this.mutateMethodDeclaration(member as MethodLikeProperty));
          break;
        case ts.SyntaxKind.PropertyDeclaration:
          members.push(...util.asArray(this.mutatePropertyDeclaration(member as ts.PropertyDeclaration)));
          break;
        case ts.SyntaxKind.IndexSignature:
        default:
          members.push(member);
      }
    }

    this.addInitializers(node, members);
    this.declareTypeParameters(node, members);
    this.assertImplementing(node, members);
    this.setMerged(node);

    // Combine decorators and modifiers for TypeScript 4.8+
    // In TS 4.8+, decorators are passed as modifiers
    const modifiers = ts.canHaveModifiers(node) ? ts.getModifiers(node) : undefined;
    const allModifiers = decorators && modifiers
      ? [...(decorators as any), ...modifiers]
      : decorators as any || modifiers;

    return ts.factory.updateClassDeclaration(
      node, allModifiers, node.name,
      node.typeParameters, node.heritageClauses, members
    );
  }

  private setMerged(node: ts.ClassDeclaration) {
    const nodeSymbol = this.scanner.getNodeSymbol(node.name);
    this.context.setMerged(nodeSymbol);
  }

  private reflectClass(node: ts.ClassDeclaration): ts.Decorator[] {
    const classReflection = this.factory.classReflection(node);
    const existingDecorators = ts.canHaveDecorators(node) ? ts.getDecorators(node) : undefined;
    const decorators = existingDecorators ? Array.from(existingDecorators) : [];
    const decorator = ts.factory.createDecorator(this.factory.annotate(classReflection));

    decorators.unshift(decorator);

    return decorators;
  }

  private addInitializers(node: ts.ClassDeclaration, members: ts.ClassElement[]): void {
    if (this.initializers.length === 0) {
      return;
    }

    const constructor = this.getConstructor(members);
    let statements = util.arrayFromNodeArray(constructor.body.statements);

    for (let initializer of this.initializers) {
      statements = util.insertAfterSuper(statements, initializer);
    }

    this.updateConstructor(members, constructor, statements);
  }

  private assertImplementing(node: ts.ClassDeclaration, members: ts.ClassElement[]): ts.ClassElement[] {
    const implementsClause = util.getImplementsClause(node);

    if (!implementsClause) {
      return members;
    }

    let constructor = this.getConstructor(members);
    let statements = util.arrayFromNodeArray(constructor.body.statements);

    for (let impl of implementsClause.types || []) {
      const assertion = ts.factory.createExpressionStatement(
        this.factory.typeAssertion(
          this.factory.expressionWithTypeArgumentsReflection(impl),
          ts.factory.createThis()
        )
      );

      statements.push(assertion);
    }

    this.updateConstructor(members, constructor, statements);

    return members;
  }

  private declareTypeParameters(node: ts.ClassDeclaration, members: ts.ClassElement[]): ts.ClassElement[] {
    const extendsClause = util.getExtendsClause(node);
    const hasTypeParameters = util.hasTypeParameters(node);
    const extendsClauseHasTypeArguments = util.extendsClauseHasTypeArguments(extendsClause);

    if (!hasTypeParameters && !extendsClauseHasTypeArguments) {
      return members;
    }

    let constructor = this.getConstructor(members);
    let statements: ts.Statement[] = util.arrayFromNodeArray(constructor.body.statements);

    let typeParametersStatement: ts.Statement;
    let thisStatement: ts.Statement;
    let bindStatement: ts.Statement;

    const insert: ts.Statement[] = [];

    if (hasTypeParameters) {
      typeParametersStatement = this.factory.typeParametersLiteralDeclaration(util.arrayFromNodeArray(node.typeParameters));
      thisStatement = this.factory.classTypeParameterSymbolConstructorDeclaration(node.name);
      insert.push(typeParametersStatement);
    }

    if (extendsClauseHasTypeArguments) {
      bindStatement = this.factory.typeParameterBindingDeclaration(
        util.arrayFromNodeArray(extendsClause.types[0].typeArguments)
      );
    }

    insert.push(...[thisStatement, bindStatement].filter(statement => !!statement));
    util.insertAfterSuper(statements, insert);
    this.updateConstructor(members, constructor, statements);

    if (hasTypeParameters) {
      members.unshift(this.factory.classTypeParameterSymbolPropertyDeclaration(node.name));
    }

    return members;
  }

  private mutatePropertyDeclaration(node: ts.PropertyDeclaration): PropertySubstitution | PropertySubstitution[] {
    if (!this.options.assertAny && this.context.isAny(node.type)) {
      return node;
    }

    if (ts.isComputedPropertyName(node.name)) {
      return node;
    }

    if (util.hasModifier(node, ts.SyntaxKind.AbstractKeyword)) {
      return node;
    }

    const isStatic = util.isStatic(node);
    const className = (this.node as ts.ClassDeclaration).name.text;

    // Use decorators for static properties temporarily
    // if (util.isStatic(node)) {
    //   const decorators = util.asNewArray(node.decorators);
    //
    //   if (node.initializer) {
    //     const typeReflection = this.factory.typeReflection(node.type);
    //
    //     let decorator: ts.Decorator;
    //
    //     if (util.hasKind(typeReflection, ts.SyntaxKind.ThisKeyword)) {
    //       decorator = ts.factory.createDecorator(this.factory.decorate(
    //         ts.factory.createFunctionExpression(undefined, undefined, undefined, undefined, undefined, undefined,
    //           ts.factory.createBlock([ts.factory.createReturn(typeReflection)], true)
    //         )
    //       ));
    //     } else {
    //       decorator = ts.factory.createDecorator(this.factory.decorate(typeReflection));
    //     }
    //
    //     decorators.unshift(decorator);
    //   }
    //
    //   return ts.factory.updatePropertyDeclaration(node, decorators, node.modifiers, node.name, node.type, node.initializer);
    // }

    let name = node.name.text;
    if (!ts.isComputedPropertyName(node.name)) {
      name = this.context.getPropertyName(this.node as ts.ClassDeclaration, `_${node.name.text}`)
    }

    let initializer: ts.Expression = undefined;

    if (node.initializer) {
      initializer = this.factory.typeReflectionAndAssertion(node.type, node.initializer);
    }

    if (!isStatic && initializer) {
      this.initializers.push(ts.factory.createExpressionStatement(
        ts.factory.createBinaryExpression(
          ts.factory.createPropertyAccessExpression(isStatic ? ts.factory.createIdentifier(className) : ts.factory.createThis(), name),
          ts.SyntaxKind.FirstAssignment,
          initializer
        )
      ));
    }

    // Combine decorators and modifiers for TypeScript 4.8+
    const decorators = ts.canHaveDecorators(node) ? ts.getDecorators(node) : undefined;
    const modifiers = ts.canHaveModifiers(node) ? ts.getModifiers(node) : undefined;
    const allModifiers = decorators && modifiers
      ? [...(decorators as any), ...modifiers]
      : decorators as any || modifiers;

    const property = this.map(
      ts.factory.updatePropertyDeclaration(node, allModifiers, ts.factory.createIdentifier(name), node.questionToken, node.type, isStatic ? initializer : undefined),
      node);

    let setAccessor: ts.SetAccessorDeclaration;
    if (!util.hasModifier(node, ts.SyntaxKind.ReadonlyKeyword)) {
      setAccessor = this.factory.mutateFunctionBody(ts.factory.createSetAccessorDeclaration(ts.canHaveModifiers(node) ? ts.getModifiers(node) : undefined, node.name, [
        ts.factory.createParameterDeclaration(undefined, undefined, node.name.text, undefined, node.type)
      ], ts.factory.createBlock([ts.factory.createExpressionStatement(
        ts.factory.createBinaryExpression(ts.factory.createPropertyAccessExpression(isStatic ? ts.factory.createIdentifier(className) : ts.factory.createThis(), name), ts.SyntaxKind.FirstAssignment, node.name as ts.Expression)
      )], true
      ))) as ts.SetAccessorDeclaration;
    }

    const getAccessor = ts.factory.createGetAccessorDeclaration(ts.canHaveModifiers(node) ? ts.getModifiers(node) : undefined, node.name, undefined, node.type, ts.factory.createBlock(
      [ts.factory.createReturnStatement(
        ts.factory.createPropertyAccessExpression(
          isStatic ? ts.factory.createIdentifier(className) : ts.factory.createThis(),
          name
        )
      )], true
    ));

    // TODO: fix any cast
    (node.name as any) = ts.factory.createIdentifier(name);

    return [property, getAccessor, setAccessor].filter(val => !!val);
  }

  // TODO: assert parameters and return type is isImplementationOfOverload
  private mutateMethodDeclaration(node: MethodLikeProperty): MethodLikeProperty {
    return this.factory.mutateFunctionBody(node) as MethodLikeProperty;
  }

  private getConstructor(members: ts.ClassElement[], create = true): ts.ConstructorDeclaration {
    const index = members.findIndex(member => member.kind === ts.SyntaxKind.Constructor);
    const exists = index !== -1;

    if (exists) {
      return members[index] as ts.ConstructorDeclaration;
    }

    if (!create) {
      return null;
    }

    const extendsClause = util.getExtendsClause(this.node as ts.ClassDeclaration);
    const isExtending = !!extendsClause;

    const constructor = ts.factory.createConstructorDeclaration(
      undefined,
      isExtending
        ? [ts.factory.createParameterDeclaration(undefined, ts.factory.createToken(ts.SyntaxKind.DotDotDotToken), 'args')]
        : undefined,
      ts.factory.createBlock(
        isExtending
          ? [ts.factory.createExpressionStatement(
            ts.factory.createCallExpression(ts.factory.createSuper(), undefined, [ts.factory.createSpreadElement(ts.factory.createIdentifier('args'))])
          )] : [],
        true
      )
    );

    return constructor;
  }

  private updateConstructor(members: ts.ClassElement[], constructor: ts.ConstructorDeclaration, statements: ts.Statement[]): ts.ClassElement[] {
    const index = members.findIndex(member => member.kind === ts.SyntaxKind.Constructor);
    const exists = index !== -1;

    // Combine decorators and modifiers for TypeScript 4.8+
    const constructorDecorators = ts.canHaveDecorators(constructor) ? ts.getDecorators(constructor) : undefined;
    const constructorModifiers = ts.canHaveModifiers(constructor) ? ts.getModifiers(constructor) : undefined;
    const constructorAllModifiers = constructorDecorators && constructorModifiers
      ? [...(constructorDecorators as any), ...constructorModifiers]
      : constructorDecorators as any || constructorModifiers;

    constructor = this.map(ts.factory.updateConstructorDeclaration(
      constructor,
      constructorAllModifiers,
      constructor.parameters,
      this.map(ts.factory.updateBlock(constructor.body, statements), constructor.body)
    ), constructor);

    if (exists) {
      members[index] = constructor;
    } else {
      members.unshift(constructor);
    }

    return members;
  }

}
